#include <string>
#include <vector>
#include <queue>

class Solution {
public:
    bool isTransformable(std::string s, std::string t) {
        std::vector<std::queue<int>> pos(10);
        for (int i = 0; i < (int)s.size(); ++i) pos[s[i] - '0'].push(i);
        for (char ch : t) {
            int d = ch - '0';
            if (pos[d].empty()) return false;
            int idx = pos[d].front();
            for (int smaller = 0; smaller < d; ++smaller) {
                if (!pos[smaller].empty() && pos[smaller].front() < idx) return false;
            }
            pos[d].pop();
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean isTransformable(String s, String t) {
        Queue<Integer>[] pos = new Queue[10];
        for (int i = 0; i < 10; i++) pos[i] = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) pos[s.charAt(i) - '0'].add(i);
        for (int i = 0; i < t.length(); i++) {
            int d = t.charAt(i) - '0';
            if (pos[d].isEmpty()) return false;
            int idx = pos[d].peek();
            for (int smaller = 0; smaller < d; smaller++) {
                if (!pos[smaller].isEmpty() && pos[smaller].peek() < idx) return false;
            }
            pos[d].poll();
        }
        return true;
    }
}

